import{_ as t,a0 as p,w as l,s as r,ao as d,I as i,x as s,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"“用户组”在 Linux 上到底是怎么工作的？ | LCTT x X-CMD","titleTemplate":false,"description":"“用户组”在 Linux 上到底是怎么工作的？ | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"“用户组”在 Linux 上到底是怎么工作的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"“用户组”在 Linux 上到底是怎么工作的？ | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20171124 How do groups work on Linux","title":"“用户组”在 Linux 上到底是怎么工作的？","tag":"201809","desc":""},"relativePath":"201809/20171124 How do groups work on Linux.md","filePath":"[post].md"}'),u={name:"201809/20171124 How do groups work on Linux.md"};function g(c,a,h,b,k,x){const n=p("Link");return l(),r("div",null,[a[19]||(a[19]=d('<h1 id="用户组-在-linux-上到底是怎么工作的" tabindex="-1">“用户组”在 Linux 上到底是怎么工作的？ <a class="header-anchor" href="#用户组-在-linux-上到底是怎么工作的" aria-label="Permalink to ““用户组”在 Linux 上到底是怎么工作的？”">​</a></h1><p>嗨！就在上周，我还自认为对 Linux 上的用户和组的工作机制了如指掌。我认为它们的关系是这样的：</p><ol><li>每个进程都属于一个用户（比如用户 <code>julia</code>）</li><li>当这个进程试图读取一个被某个组所拥有的文件时， Linux 会 a. 先检查用户<code>julia</code> 是否有权限访问文件。（LCTT 译注：此处应该是指检查文件的所有者是否就是 <code>julia</code>） b. 检查 <code>julia</code> 属于哪些组，并进一步检查在这些组里是否有某个组拥有这个文件或者有权限访问这个文件。</li><li>如果上述 a、b 任一为真（或者“其它”位设为有权限访问），那么这个进程就有权限访问这个文件。</li></ol><p>比如说，如果一个进程被用户 <code>julia</code> 拥有并且 <code>julia</code> 在<code>awesome</code> 组，那么这个进程就能访问下面这个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>r--r--r-- 1 root awesome     6872 Sep 24 11:09 file.txt</span></span></code></pre></div><p>然而上述的机制我并没有考虑得非常清楚，如果你硬要我阐述清楚，我会说进程可能会在<strong>运行时</strong>去检查 <code>/etc/group</code> 文件里是否有某些组拥有当前的用户。</p><h3 id="然而这并不是-linux-里-组-的工作机制" tabindex="-1">然而这并不是 Linux 里“组”的工作机制 <a class="header-anchor" href="#然而这并不是-linux-里-组-的工作机制" aria-label="Permalink to “然而这并不是 Linux 里“组”的工作机制”">​</a></h3><p>我在上个星期的工作中发现了一件有趣的事，事实证明我前面的理解错了，我对组的工作机制的描述并不准确。特别是 Linux <strong>并不会</strong>在进程每次试图访问一个文件时就去检查这个进程的用户属于哪些组。</p>',8)),i("p",null,[a[1]||(a[1]=s("我在读了《",-1)),e(n,{href:"http://man7.org/tlpi/"},{default:o(()=>[...a[0]||(a[0]=[s("Linux 编程接口",-1)])]),_:1}),a[2]||(a[2]=s("》这本书的第九章（“进程资格”）后才恍然大悟（这本书真是太棒了），这才是组真正的工作方式！我意识到之前我并没有真正理解用户和组是怎么工作的，我信心满满的尝试了下面的内容并且验证到底发生了什么，事实证明现在我的理解才是对的。",-1))]),a[20]||(a[20]=d(`<h3 id="用户和组权限检查是怎么完成的" tabindex="-1">用户和组权限检查是怎么完成的 <a class="header-anchor" href="#用户和组权限检查是怎么完成的" aria-label="Permalink to “用户和组权限检查是怎么完成的”">​</a></h3><p>现在这些关键的知识在我看来非常简单! 这本书的第九章上来就告诉我如下事实：用户和组 ID 是<strong>进程的属性</strong>，它们是：</p><ul><li>真实用户 ID 和组 ID；</li><li>有效用户 ID 和组 ID；</li><li>保存的 set-user-ID 和保存的 set-group-ID；</li><li>文件系统用户 ID 和组 ID（特定于 Linux);</li><li>补充的组 ID；</li></ul><p>这说明 Linux <strong>实际上</strong>检查一个进程能否访问一个文件所做的组检查是这样的：</p><ul><li>检查一个进程的组 ID 和补充组 ID（这些 ID 就在进程的属性里，<strong>并不是</strong>实时在 <code>/etc/group</code> 里查找这些 ID）</li><li>检查要访问的文件的访问属性里的组设置</li><li>确定进程对文件是否有权限访问（LCTT 译注：即文件的组是否是以上的组之一）</li></ul><p>通常当访问控制的时候使用的是<strong>有效</strong>用户/组 ID，而不是<strong>真实</strong>用户/组 ID。技术上来说当访问一个文件时使用的是<strong>文件系统</strong>的 ID，它们通常和有效用户/组 ID 一样。（LCTT 译注：这句话针对 Linux 而言。）</p><h3 id="将一个用户加入一个组并不会将一个已存在的进程-的用户-加入那个组" tabindex="-1">将一个用户加入一个组并不会将一个已存在的进程（的用户）加入那个组 <a class="header-anchor" href="#将一个用户加入一个组并不会将一个已存在的进程-的用户-加入那个组" aria-label="Permalink to “将一个用户加入一个组并不会将一个已存在的进程（的用户）加入那个组”">​</a></h3><p>下面是一个有趣的例子：如果我创建了一个新的组：<code>panda</code> 组并且将我自己（<code>bork</code>）加入到这个组，然后运行 <code>groups</code> 来检查我是否在这个组里：结果是我（<code>bork</code>）竟然不在这个组？！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bork@kiwi~&gt; sudo addgroup panda</span></span>
<span class="line"><span>Adding group \`panda&#39; (GID 1001) ...</span></span>
<span class="line"><span>Done.</span></span>
<span class="line"><span>bork@kiwi~&gt; sudo adduser bork panda</span></span>
<span class="line"><span>Adding user \`bork&#39; to group \`panda&#39; ...</span></span>
<span class="line"><span>Adding user bork to group panda</span></span>
<span class="line"><span>Done.</span></span>
<span class="line"><span>bork@kiwi~&gt; groups</span></span>
<span class="line"><span>bork adm cdrom sudo dip plugdev lpadmin sambashare docker lxd</span></span></code></pre></div><p><code>panda</code> 并不在上面的组里！为了再次确定我们的发现，让我们建一个文件，这个文件被 <code>panda</code> 组拥有，看看我能否访问它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$  touch panda-file.txt</span></span>
<span class="line"><span>$  sudo chown root:panda panda-file.txt</span></span>
<span class="line"><span>$  sudo chmod 660 panda-file.txt</span></span>
<span class="line"><span>$  cat panda-file.txt</span></span>
<span class="line"><span>cat: panda-file.txt: Permission denied</span></span></code></pre></div><p>好吧，确定了，我（<code>bork</code>）无法访问 <code>panda-file.txt</code>。这一点都不让人吃惊，我的命令解释器并没有将 <code>panda</code> 组作为补充组 ID，运行 <code>adduser bork panda</code> 并不会改变这一点。</p><h3 id="那进程一开始是怎么得到用户的组的呢" tabindex="-1">那进程一开始是怎么得到用户的组的呢？ <a class="header-anchor" href="#那进程一开始是怎么得到用户的组的呢" aria-label="Permalink to “那进程一开始是怎么得到用户的组的呢？”">​</a></h3><p>这真是个非常令人困惑的问题，对吗？如果进程会将组的信息预置到进程的属性里面，进程在初始化的时候怎么取到组的呢？很明显你无法给你自己指定更多的组（否则就会和 Linux 访问控制的初衷相违背了……）</p><p>有一点还是很清楚的：一个新的进程是怎么从我的命令行解释器（<code>/bash/fish</code>）里被<strong>执行</strong>而得到它的组的。（新的）进程将拥有我的用户 ID（<code>bork</code>），并且进程属性里还有很多组 ID。从我的命令解释器里执行的所有进程是从这个命令解释器里 <code>fork()</code> 而来的，所以这个新进程得到了和命令解释器同样的组。</p><p>因此一定存在一个“第一个”进程来把你的组设置到进程属性里，而所有由此进程而衍生的进程将都设置这些组。而那个“第一个”进程就是你的<ruby>登录程序<rt>login shell</rt></ruby>，在我的笔记本电脑上，它是由 <code>login</code> 程序（<code>/bin/login</code>）实例化而来。登录程序以 root 身份运行，然后调用了一个 C 的库函数 —— <code>initgroups</code> 来设置你的进程的组（具体来说是通过读取 <code>/etc/group</code> 文件），因为登录程序是以 root 运行的，所以它能设置你的进程的组。</p><h3 id="让我们再登录一次" tabindex="-1">让我们再登录一次 <a class="header-anchor" href="#让我们再登录一次" aria-label="Permalink to “让我们再登录一次”">​</a></h3><p>好了！假如说我们正处于一个登录程序中，而我又想刷新我的进程的组设置，从我们前面所学到的进程是怎么初始化组 ID 的，我应该可以通过再次运行登录程序来刷新我的进程组并启动一个新的登录命令！</p><p>让我们试试下边的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo login bork</span></span>
<span class="line"><span>$ groups</span></span>
<span class="line"><span>bork adm cdrom sudo dip plugdev lpadmin sambashare docker lxd panda</span></span>
<span class="line"><span>$ cat panda-file.txt # it works! I can access the file owned by \`panda\` now!</span></span></code></pre></div><p>当然，成功了！现在由登录程序衍生的程序的用户是组 <code>panda</code> 的一部分了！太棒了！这并不会影响我其他的已经在运行的登录程序（及其子进程），如果我真的希望“所有的”进程都能对 <code>panda</code> 组有访问权限。我必须完全的重启我的登录会话，这意味着我必须退出我的窗口管理器然后再重新登录。（LCTT 译注：即更新进程树的树根进程，这里是窗口管理器进程。）</p><h3 id="newgrp-命令" tabindex="-1">newgrp 命令 <a class="header-anchor" href="#newgrp-命令" aria-label="Permalink to “newgrp 命令”">​</a></h3><p>在 Twitter 上有人告诉我如果只是想启动一个刷新了组信息的命令解释器的话，你可以使用 <code>newgrp</code>（LCTT 译注：不启动新的命令解释器），如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo addgroup panda</span></span>
<span class="line"><span>sudo adduser bork panda</span></span>
<span class="line"><span>newgrp panda # starts a new shell, and you don&#39;t have to be root to run it!</span></span></code></pre></div><p>你也可以用 <code>sg panda bash</code> 来完成同样的效果，这个命令能启动一个<code>bash</code> 登录程序，而这个程序就有 <code>panda</code> 组。</p><h3 id="seduid-将设置有效用户-id" tabindex="-1">seduid 将设置有效用户 ID <a class="header-anchor" href="#seduid-将设置有效用户-id" aria-label="Permalink to “seduid 将设置有效用户 ID”">​</a></h3><p>其实我一直对一个进程如何以 <code>setuid root</code> 的权限来运行意味着什么有点似是而非。现在我知道了，事实上所发生的是：<code>setuid</code> 设置了 “有效用户 ID”! 如果我（<code>julia</code>）运行了一个 <code>setuid root</code> 的进程（ 比如 <code>passwd</code>），那么进程的<strong>真实</strong>用户 ID 将为 <code>julia</code>，而<strong>有效</strong>用户 ID 将被设置为 <code>root</code>。</p><p><code>passwd</code> 需要以 root 权限来运行，但是它能看到进程的真实用户 ID 是 <code>julia</code> ，是 <code>julia</code> 启动了这个进程，<code>passwd</code> 会阻止这个进程修改除了 <code>julia</code> 之外的用户密码。</p><h3 id="就是这些了" tabindex="-1">就是这些了！ <a class="header-anchor" href="#就是这些了" aria-label="Permalink to “就是这些了！”">​</a></h3>`,29)),i("p",null,[a[4]||(a[4]=s("在《",-1)),e(n,{href:"http://man7.org/tlpi/"},{default:o(()=>[...a[3]||(a[3]=[s("Linux 编程接口",-1)])]),_:1}),a[5]||(a[5]=s("》这本书里有很多 Linux 上一些功能的罕见使用方法以及 Linux 上所有的事物到底是怎么运行的详细解释，这里我就不一一展开了。那本书棒极了，我上面所说的都在该书的第九章，这章在 1300 页的书里只占了 17 页。",-1))]),a[21]||(a[21]=i("p",null,"我最爱这本书的一点是我只用读 17 页关于用户和组是怎么工作的内容，而这区区 17 页就能做到内容完备、详实有用。我不用读完所有的 1300 页书就能得到有用的东西，太棒了！",-1)),a[22]||(a[22]=i("hr",null,null,-1)),i("p",null,[a[7]||(a[7]=s("via: ",-1)),e(n,{href:"https://jvns.ca/blog/2017/11/20/groups/"},{default:o(()=>[...a[6]||(a[6]=[s("https://jvns.ca/blog/2017/11/20/groups/",-1)])]),_:1})]),i("p",null,[a[11]||(a[11]=s("作者：",-1)),e(n,{href:"https://jvns.ca/"},{default:o(()=>[...a[8]||(a[8]=[s("Julia Evans",-1)])]),_:1}),a[12]||(a[12]=s(" 译者：",-1)),e(n,{href:"https://github.com/DavidChenLiang"},{default:o(()=>[...a[9]||(a[9]=[s("DavidChen",-1)])]),_:1}),a[13]||(a[13]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[10]||(a[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[16]||(a[16]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[14]||(a[14]=[s("LCTT",-1)])]),_:1}),a[17]||(a[17]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...a[15]||(a[15]=[s("Linux中国",-1)])]),_:1}),a[18]||(a[18]=s(" 荣誉推出",-1))])])}const L=t(u,[["render",g]]);export{D as __pageData,L as default};
